 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find diagonal same-color runs and continue each run's direction to the edge.
    runs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or all(color == row[0] for row in grid):
                continue
            for dr, dc in ((1, -1), (1, 1)):
                nr, nc = r + dr, c + dc
                if nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    # Use only the start of a maximal run in this direction.
                    if r > 0 and 0 <= c - dc < w and grid[r-1][c-dc] == color:
                        continue
                    rr, cc = nr, nc
                    while rr + dr < h and 0 <= cc + dc < w and cc + dc >= 0 and grid[rr+dr][cc+dc] == color:
                        rr, cc = rr + dr, cc + dc
                    runs.append((rr, cc, dr, dc, color))
    for r, c, dr, dc, color in runs:
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] != grid[0][0]:
                break
            out[r][c] = color
            r += dr
            c += dc
    return out
